record.field:
MODES = {"on": "Activar", "off": "Desactivar", "set": "Poner", "add": "Añadir",
         "remove": "Quitar", "replace": "Sustituir por"}
for line in self:
    op = line.x_operation
    mode = MODES.get(line.x_mode, "")
    amount = "%.2f" % line.x_value_float
    if op == "pos_available":
        text = mode
    elif op in ("list_price", "standard_price"):
        text = amount
    elif op == "supplier_price":
        text = "%s · %s" % (amount, ", ".join(line.x_supplier_ids.mapped("display_name")))
    elif op == "pricelist_price":
        names = ", ".join(line.x_pricelist_ids.mapped("display_name"))
        text = ("Quitar de %s" % names) if line.x_mode == "remove" else ("%s en %s" % (amount, names))
    elif op == "name":
        text = "«%s» (%s)" % (line.x_value_char or "", line.x_lang_id.name or "todos los idiomas")
    elif op in ("pos_categ", "pos_categories"):
        text = "%s %s" % (mode, ", ".join(line.x_pos_categ_ids.mapped("display_name")))
    elif op == "combos":
        text = "%s %s" % (mode, ", ".join(line.x_combo_ids.mapped("display_name")))
    else:
        text = ""
    line["x_summary"] = text
